## Target contract: `Token`
A bare call head (no `<var>.` prefix) targets this contract. Its callable functions (exact signatures from the ABI):
- balanceOf(address _owner) -> uint256  [view]
- totalSupply() -> uint256  [view]
- transfer(address _to, uint256 _value) -> bool

## Contract Source
```solidity
pragma solidity ^0.4.18;

contract Token {

mapping(address => uint) balances;
uint public totalSupply;

function Token(uint _initialSupply) {
balances[msg.sender] = totalSupply = _initialSupply;
}

function transfer(address _to, uint _value) public returns (bool) {

require(balances[msg.sender] - _value >= 0);

balances[msg.sender] -= _value;
balances[_to] += _value;
return true;
}

function balanceOf(address _owner) public constant returns (uint balance) {
return balances[_owner];
}
}
```

